use std::fs

trait Pricing {
    fn total(&self, qty: int, unit: int) -> int
}

struct Plain {}
struct Bulk {}
struct Member {}

impl Pricing for Plain {
    fn total(self, qty: int, unit: int) -> int {
        qty * unit
    }
}

impl Pricing for Bulk {
    fn total(self, qty: int, unit: int) -> int {
        let base = qty * unit
        if qty >= 10 {
            base - base * 10 / 100
        } else {
            base
        }
    }
}

impl Pricing for Member {
    fn total(self, qty: int, unit: int) -> int {
        let base = qty * unit
        let mut t = base - base * 5 / 100
        if qty >= 3 {
            t -= 100
        }
        if t < 0 {
            t = 0
        }
        t
    }
}

fn money(c: int) -> string {
    let cents = c % 100
    let d = c / 100
    let dollar = "$"
    if cents < 10 {
        "${dollar}${d}.0${cents}"
    } else {
        "${dollar}${d}.${cents}"
    }
}

fn price(kind: string, qty: int, unit: int) -> Option<int> {
    if kind == "plain" {
        Some(Plain {}.total(qty, unit))
    } else if kind == "bulk" {
        Some(Bulk {}.total(qty, unit))
    } else if kind == "member" {
        Some(Member {}.total(qty, unit))
    } else {
        None
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut sum = 0
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() < 4 {
            continue
        }
        let qty: int = parts[1].parse::<int>().unwrap_or(0)
        let unit: int = parts[2].parse::<int>().unwrap_or(0)
        match price(parts[3], qty, unit) {
            Some(t) => {
                sum += t
                println("${parts[0]} ${money(t)}")
            }
            None => println("${parts[0]} invalid kind"),
        }
    }
    println("total ${money(sum)}")
}

